import { Avatar, AvatarFallback, AvatarImage } from "@/registry/erbium/ui/avatar";
import { Button } from "@/registry/erbium/ui/button";
import { HoverCard, HoverCardContent, HoverCardTrigger } from "@/registry/erbium/ui/hover-card";

export default function HoverCardExample() {
  return (
    <HoverCard>
      <HoverCardTrigger render={<Button variant="link">@erbium</Button>} />
      <HoverCardContent className="w-80">
        <div className="flex justify-between gap-group">
          <Avatar>
            <AvatarImage
              src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2264%22%20height%3D%2264%22%20viewBox%3D%220%200%2064%2064%22%3E%3Crect%20width%3D%2264%22%20height%3D%2264%22%20rx%3D%2232%22%20fill%3D%22%2352525b%22%2F%3E%3Ctext%20x%3D%2232%22%20y%3D%2233%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%20font-family%3D%22sans-serif%22%20font-size%3D%2222%22%20fill%3D%22white%22%3EEU%3C%2Ftext%3E%3C%2Fsvg%3E"
              alt="Erbium UI"
            />
            <AvatarFallback>EU</AvatarFallback>
          </Avatar>
          <div className="space-y-1">
            <h4 className="text-subtitle">@erbium</h4>
            <p className="text-caption">Accessible components for building your next interface.</p>
            <div className="text-metadata text-muted-foreground">Joined December 2021</div>
          </div>
        </div>
      </HoverCardContent>
    </HoverCard>
  );
}
